const {test,before,after}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium}=require('playwright');let browser,server,url;const root=path.resolve(__dirname,'..');
const harness=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/practice-tools.css"><link rel="stylesheet" href="/neuro-record.css"><style>@font-face{font-family:Pretendard;src:url(/pretendard-variable-1.3.9.woff2)}body{font-family:Pretendard,sans-serif;margin:14px;background:#f5f7fb}</style><main id="root"></main><script src="/neuro-record.js"></script><script>
window.state={scope:'test:owner',canEdit:true,records:JSON.parse(sessionStorage.getItem('mock-records')||'[]'),requests:[],keys:{},fail:false};
const patient={id:'p1',name:'합성 환자',species:'dog',breed:'합성 품종',sex:'male',neutered:'yes',birthDate:'2020-01-01',latestWeightKg:5,guardianName:'합성 보호자',chartNumber:'TEST-101'};
window.api=async(p,o={})=>{state.requests.push({p,...o});if(state.fail)throw Error('합성 네트워크 실패');if(p.startsWith('/patient-directory'))return {patients:[patient],pagination:{hasNext:false}};if(p.endsWith('/members'))return {userId:'u',members:[{id:'u',display_name:'시험 검사자'}]};if(p.startsWith('/intakes'))return {items:[],next:null};const b=o.body?JSON.parse(o.body):null;
if(p.includes('/neuro?')){if(state.pages)return state.pages[new URL('https://test'+p).searchParams.get('cursor')||'first'];const q=new URL('https://test'+p).searchParams;return {items:state.records.filter(r=>!r.body.deleted&&(!q.get('patientId')||r.patient_id===q.get('patientId'))&&(!q.get('status')||r.body.neuroChart.clinicalStatus===q.get('status'))).map(r=>({id:r.id,patient:{...r.patient,...r.body.neuroChart.patient},date:r.body.neuroChart.date,diagnosis:r.body.neuroChart.assessment,clinicalStatus:r.body.neuroChart.clinicalStatus})),next:null};}
if(b?.requestKey&&state.keys[b.requestKey]){const saved=state.keys[b.requestKey];return {id:saved.id,revision:saved.revision,replayed:true};}
if(p.endsWith('/cases')&&o.method==='POST'){const r={id:'n'+(state.records.length+1),revision:1,patient_id:b.patientId||'',patient:b.patientId?patient:{...b.quickPatient,species:b.species},body:{species:b.species,category:'neuro',previousId:b.previousId,neuroChart:structuredClone(b.neuroChart)}};state.records.push(r);sessionStorage.setItem('mock-records',JSON.stringify(state.records));const out={id:r.id,revision:1,neuroChart:structuredClone(b.neuroChart)};state.keys[b.requestKey]=out;if(state.loseResponse){state.loseResponse=false;throw Error('합성 응답 유실');}return out;}
const id=p.split('/cases/')[1]?.split(/[/?]/)[0],r=state.records.find(x=>x.id===id);if(o.method==='POST'){if(b.revision!==r.revision)throw Object.assign(Error('다른 직원이 기록했습니다.'),{status:409});if(b.kind==='case.delete')r.body.deleted=true;else {if(r.body.neuroChart.clinicalStatus==='complete'&&b.data.clinicalStatus==='complete'&&JSON.stringify(r.body.neuroChart)!==JSON.stringify(b.data))b.data.clinicalStatus='amended';r.body.neuroChart=structuredClone(b.data);}r.revision++;sessionStorage.setItem('mock-records',JSON.stringify(state.records));const out={id:r.id,revision:r.revision,neuroChart:structuredClone(r.body.neuroChart)};state.keys[b.requestKey]=out;return out;}
if(!r||r.body.deleted)throw Error('기록 없음');if(p.endsWith('/sync'))return {revision:r.revision};return {item:structuredClone(r),canManage:state.canEdit};};
window.opts={ready:()=>true,identity:()=>state.scope,can:k=>k!=='records.edit'||state.canEdit,medical:()=>state.canEdit,clinicalManage:()=>state.canEdit,request:(p,o)=>api(p,o),patient:()=>null,clinicName:()=> '합성 시험 병원'};window.view=NeuroRecord.mount(document.querySelector('#root'),opts);view.open();</script>`;
before(async()=>{server=http.createServer((req,res)=>{const name=new URL(req.url,'http://local').pathname.slice(1);if(!name){res.setHeader('Content-Type','text/html; charset=utf-8');res.end(harness);return;}const file=path.join(root,name);if(!fs.existsSync(file)){res.writeHead(404);res.end();return;}res.setHeader('Content-Type',name.endsWith('.css')?'text/css':'application/javascript');res.end(fs.readFileSync(file));});await new Promise(r=>server.listen(0,'127.0.0.1',r));url='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({executablePath:process.env.HQ_TEST_BROWSER||'/tmp/clinic-chromium',headless:true});});
after(async()=>{await browser?.close();server.closeAllConnections();await new Promise(r=>server.close(r));});
async function page(width=1440){const p=await browser.newPage({viewport:{width,height:900}});p.setDefaultTimeout(7000);await p.goto(url);await p.locator('[data-nr=new]').waitFor();return p;}
async function quick(p){await p.locator('[data-nr=new]').click();await p.locator('[data-identity=name]').fill('합성 신경환자');await p.locator('[data-species]').selectOption('cat');await p.locator('[data-field="patient.guardianName"]').fill('시험 보호자');await p.locator('[data-field="patient.chartNumber"]').fill('Q-TEST');}
async function begin(p){await quick(p);await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').waitFor();}
async function save(p){await p.locator('[data-nr=save]').click();await p.waitForFunction(()=>document.querySelector('[data-nr=save]')?.textContent==='저장됨');}
test('neuro quick setup is explicit and unexamined findings remain blank',async()=>{const p=await page();await quick(p);await p.waitForTimeout(1200);assert.equal(await p.evaluate(()=>state.records.length),0);assert.equal(await p.locator('[data-finding]').count(),0);await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').waitFor();assert.equal(await p.locator('[data-field=veterinarian]').inputValue(),'시험 검사자');assert.equal(await p.locator('[data-finding="position.LF"]').inputValue(),'');assert.equal(await p.evaluate(()=>Object.keys(state.records[0].body.neuroChart.findings).length),0);await p.close();});
test('neuro registered patient links identity and existing demographic fields',async()=>{const p=await page();await p.locator('[data-nr=new]').click();await p.locator('[data-patient-search]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick]').click();assert.equal(await p.locator('[data-identity=name]').inputValue(),'합성 환자');assert.ok(await p.locator('[data-identity=name]').getAttribute('readonly')!==null);await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').waitFor();assert.match(await p.locator('[data-patient-brief]').innerText(),/합성 보호자.*TEST-101/);assert.equal(await p.locator('[data-field=weight]').inputValue(),'5');assert.equal(await p.locator('[data-field="patient.chartNumber"]').count(),0);await p.close();});
test('neuro autosaves findings, shows abnormal summary, and reloads without inferring pain',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LH"]').selectOption('delayed');await p.locator('[data-finding="withdrawal.LH"]').selectOption('normal');await p.waitForFunction(()=>state.records[0].body.neuroChart.findings['position.LH']==='delayed');assert.match(await p.locator('[data-summary]').innerText(),/발 위치반응.*좌후.*지연/);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings['deepPain.LH']),undefined);await p.reload();await p.locator('[data-finding="position.LH"]').waitFor();assert.equal(await p.locator('[data-finding="position.LH"]').inputValue(),'delayed');assert.ok(!await p.locator('[data-finding="deepPain.LH"]').isVisible());await p.close();});
test('neuro failed save keeps typed values and retry uses same creation key',async()=>{const p=await page();await quick(p);await p.evaluate(()=>state.loseResponse=true);await p.locator('[data-nr=save]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.locator('[data-identity=name]').inputValue(),'합성 신경환자');await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').waitFor();assert.equal(await p.evaluate(()=>state.records.length),1);assert.equal(await p.evaluate(()=>new Set(state.requests.filter(r=>r.p.endsWith('/cases')&&r.method==='POST').map(r=>JSON.parse(r.body).requestKey)).size),1);await p.locator('[data-field=assessment]').fill('실패시 보존');await p.evaluate(()=>state.fail=true);await p.locator('[data-nr=save]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.locator('[data-field=assessment]').inputValue(),'실패시 보존');await p.close();});
test('neuro same-field conflicts require explicit choice and preserve unrelated remote edits',async()=>{const p=await page();await begin(p);await p.locator('[data-field=assessment]').fill('내 판단');await p.evaluate(()=>{const r=state.records[0];r.revision++;r.body.neuroChart.assessment='다른 판단';r.body.neuroChart.plan='원격 계획';});await p.locator('[data-nr=save]').click();await p.locator('[data-resolution=assessment]').waitFor();await p.locator('[data-resolve]').click();assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.assessment),'다른 판단');await p.locator('[data-resolution=assessment]').selectOption('local');await p.locator('[data-resolve]').click();await p.waitForFunction(()=>state.records[0].body.neuroChart.assessment==='내 판단');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.plan),'원격 계획');await p.close();});
test('neuro recheck copies patient only and compares recorded changes',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LH"]').selectOption('absent');await save(p);await p.locator('[data-nr=recheck]').click();assert.equal(await p.locator('[data-identity=name]').inputValue(),'합성 신경환자');await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LH"]').waitFor();assert.equal(await p.locator('[data-finding="position.LH"]').inputValue(),'');await p.locator('[data-finding="position.LH"]').selectOption('normal');await save(p);await p.locator('[data-nr=history]').click();await p.locator('[data-prior-choice]').selectOption('n1');await p.locator('.nr-comparison').waitFor();assert.match(await p.locator('.nr-comparison').innerText(),/소실[\s\S]*정상/);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings['position.LH']),'absent');await p.close();});
test('neuro read-only disables editing and print includes saved findings identity and untested count',async()=>{const p=await page();await begin(p);await p.locator('[data-field=assessment]').fill('<script>bad()</script>');await p.locator('[data-finding="position.LH"]').selectOption('delayed');await save(p);await p.evaluate(async()=>{view.dispose();state.canEdit=false;view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});assert.equal(await p.locator('[data-nr=save]').count(),0);assert.equal(await p.locator('[data-nr=delete]').count(),0);assert.ok(await p.locator('[data-finding="position.LH"]').isDisabled());const wait=p.waitForEvent('popup');if(!await p.locator('[data-detail=print-options]').getAttribute('open').then(v=>v!==null))await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-nr=print]').click();const out=await wait;await out.waitForLoadState();const text=await out.locator('body').innerText();assert.match(text,/Q-TEST/);assert.match(text,/좌후/);assert.match(text,/발 위치반응[\s\S]*지연/);assert.match(text,/미검사/);assert.match(text,/<script>bad/);assert.equal(await out.locator('script').count(),0);await out.close();await p.close();});
test('neuro removal confirmation hides record and list shows next page explicitly',async()=>{const p=await page();await begin(p);p.once('dialog',d=>d.dismiss());await p.locator('[data-nr=delete]').click();assert.equal(await p.evaluate(()=>!!state.records[0].body.deleted),false);p.once('dialog',d=>d.accept());await p.locator('[data-nr=delete]').click();await p.locator('[data-nr=new]').waitFor();assert.equal(await p.locator('[data-record]').count(),0);await p.evaluate(()=>state.pages={first:{items:[],next:'next'},next:{items:[{id:'n2',date:'2026-11-01',patient:{name:'이전 환자'}}],next:null}});await p.locator('[data-nr=refresh]').click();await p.locator('[data-more]').click();await p.locator('[data-record=n2]').waitFor();await p.close();});
test('neuro validation blocks impossible dates and weight; localization pending is exclusive',async()=>{const p=await page();await quick(p);await p.locator('[data-field=weight]').fill('-1');await p.locator('[data-nr=save]').click();assert.equal(await p.evaluate(()=>state.records.length),0);await p.locator('[data-field=weight]').fill('4');await p.locator('[data-field=date]').fill('202611-01-01');await p.locator('[data-nr=save]').click();assert.equal(await p.evaluate(()=>state.records.length),0);await p.locator('[data-field=date]').fill('2026-11-01');await p.locator('[data-nr=save]').click();await p.locator('[data-location="T3-L3"]').check();await p.locator('[data-location=undetermined]').check();assert.ok(!await p.locator('[data-location="T3-L3"]').isChecked());await save(p);assert.deepEqual(await p.evaluate(()=>state.records[0].body.neuroChart.localization),['undetermined']);await p.close();});
test('neuro switching practice tabs flushes pending input and preserves sidebar position order',async()=>{const p=await page();await p.addScriptTag({url:url+'/practice-tools.js'});await p.evaluate(()=>{view.dispose();window.practice=PracticeTools.mount(document.querySelector('#root'),opts);practice.prepareTab('neuro');return practice.open();});await p.locator('[data-nr=new]').click();await p.locator('[data-identity=name]').fill('탭 이동 환자');await p.locator('[data-species]').selectOption('dog');await p.locator('[data-nr=save]').click();await p.locator('[data-field=assessment]').fill('이동 전 소견');await p.evaluate(()=>practice.prepareTab('intake'));await p.waitForFunction(()=>practice.route()==='intake');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.assessment),'이동 전 소견');const html=fs.readFileSync(path.join(root,'index.html'),'utf8');assert.ok(html.indexOf('data-tab="neuro"')>html.indexOf('data-tab="dental"'));assert.ok(html.indexOf('data-tab="neuro"')<html.indexOf('data-tab="protocols"'));await p.close();});
test('neuro permission scope changes clear visible patient data and stale responses',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{state.scope='other';view.sync();});assert.equal(await p.locator('[data-finding]').count(),0);assert.doesNotMatch(await p.locator('#root').innerText(),/합성 신경환자/);await p.close();});
for(const width of [360,820,1440])test('neuro responsive chart and collapsed detail '+width,async()=>{const p=await page(width),errors=[];p.on('pageerror',e=>errors.push(e.message));await begin(p);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.locator('[data-finding="position.RH"]').selectOption('delayed');await p.locator('#nr-pain > details > summary').click();await p.locator('[data-finding="deepPain.RH"]').selectOption('uncertain');await save(p);assert.match(await p.locator('[data-summary]').innerText(),/불확실/);await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:'/tmp/neuro-'+width+'.png',fullPage:true});assert.deepEqual(errors,[]);await p.close();});
test('neuro prevents stale-scope autosave before the host sync callback',async()=>{const p=await page();await begin(p);const before=await p.evaluate(()=>state.requests.filter(r=>r.method==='POST').length);await p.locator('[data-field=assessment]').fill('이전 병원 내용');await p.evaluate(()=>state.scope='new-clinic');await p.waitForTimeout(1200);assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.method==='POST').length),before);assert.equal(await p.locator('[data-field=assessment]').count(),0);await p.close();});
test('neuro in-flight saving retains newer typing and navigation waits for both writes',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const orig=api;api=async(p,o)=>{if(o?.method==='POST'&&p.endsWith('/events')&&!state.held){state.held=true;await new Promise(r=>window.releaseSave=r);}return orig(p,o);};});await p.locator('[data-field=assessment]').fill('첫 입력');await p.locator('[data-nr=save]').click();await p.waitForFunction(()=>typeof releaseSave==='function');await p.locator('[data-field=plan]').fill('저장 중 추가 계획');await p.locator('[data-nr=back]').click();await p.evaluate(()=>releaseSave());await p.locator('[data-record]').waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.plan),'저장 중 추가 계획');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.assessment),'첫 입력');await p.close();});
test('neuro print never outputs unsaved failed data and completion is explicit',async()=>{const p=await page();await begin(p);await p.locator('[data-nr=complete]').click();await p.waitForFunction(()=>state.records[0].body.neuroChart.clinicalStatus==='complete');await p.locator('[data-field=assessment]').fill('추가 검사 판단');await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.clinicalStatus),'amended');await p.locator('[data-field=plan]').fill('실패한 계획');await p.evaluate(()=>state.fail=true);const event=p.waitForEvent('popup');if(!await p.locator('[data-detail=print-options]').getAttribute('open').then(v=>v!==null))await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-nr=print]').click();const popup=await event;await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();assert.ok(popup.isClosed());await p.close();});
test('neuro background check requests only revision when unchanged and preserves unsaved input',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const now=Date.now;Date.now=()=>now()+20000;dispatchEvent(new Event('focus'));});await p.waitForFunction(()=>state.requests.some(x=>x.p.endsWith('/sync')));assert.equal(await p.evaluate(()=>state.requests.filter(x=>x.p.includes('?view=neuro')).length),0);await p.locator('[data-field=assessment]').fill('작성 중 유지');await p.evaluate(()=>{state.records[0].revision++;state.records[0].body.neuroChart.assessment='원격 변경';dispatchEvent(new Event('focus'));});assert.equal(await p.locator('[data-field=assessment]').inputValue(),'작성 중 유지');await p.close();});

test('neuro replay reconciles normalized completion and retains input typed during retry',async()=>{const p=await page();await begin(p);await p.locator('[data-nr=complete]').click();await p.waitForFunction(()=>state.records[0].body.neuroChart.clinicalStatus==='complete');await p.evaluate(()=>{const orig=api;window.onceLost=false;api=async(p,o)=>{const r=await orig(p,o);if(p.endsWith('/events')&&o?.method==='POST'&&!onceLost){onceLost=true;throw Error('응답 유실');}return r;};});await p.locator('[data-field=assessment]').fill('추가 판단');await p.locator('[data-nr=save]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();await p.locator('[data-field=plan]').fill('추가 계획');await save(p);assert.equal(await p.locator('[data-clinical-status]').innerText(),'완료 후 수정');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.plan),'추가 계획');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.clinicalStatus),'amended');await p.close();});
test('neuro creation retry keeps original endpoint if reconciliation read temporarily fails',async()=>{const p=await page();await quick(p);await p.evaluate(()=>state.loseResponse=true);await p.locator('[data-nr=save]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();await p.evaluate(()=>{const orig=api;window.failRead=true;api=async(p,o)=>{if(failRead&&p.includes('?view=neuro'))throw Error('조회 일시 실패');return orig(p,o);};});await p.locator('[data-nr=save]').click();await p.locator('[data-nr-status]').filter({hasText:'조회 일시 실패'}).waitFor();await p.evaluate(()=>failRead=false);await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').waitFor();assert.equal(await p.evaluate(()=>state.records.length),1);assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.method==='POST'&&r.p.endsWith('/events')).length),0);await p.close();});
test('neuro compact controls explicitly record pain and preserve untested fields',async()=>{const p=await page(360);await begin(p);assert.ok(!await p.locator('#nr-basic').getAttribute('open'));await p.locator('[data-jump=nr-basic]').click();assert.ok(await p.locator('#nr-basic').getAttribute('open')!==null);assert.equal(await p.locator('#nr-members option').count(),1);await p.locator('[data-quick=cervicalPain][data-value=present]').click();await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings.cervicalPain),'present');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings.lumbarPain),undefined);await p.locator('[data-quick=cervicalPain][data-value=""]').click();await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings.cervicalPain),undefined);await p.close();});
test('neuro returning to list keeps loaded pages and deletion is available from list',async()=>{const p=await page();await begin(p);await p.locator('[data-nr=back]').click();await p.locator('[data-record=n1]').waitFor();const count=await p.evaluate(()=>state.requests.filter(r=>r.p.includes('/neuro?')).length);await p.locator('[data-record=n1]').click();await p.locator('[data-field=assessment]').fill('목록 갱신 소견');await save(p);await p.locator('[data-nr=back]').click();assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('/neuro?')).length),count);assert.match(await p.locator('[data-record=n1]').innerText(),/목록 갱신 소견/);await p.locator('.nr-list-menu summary').click();p.once('dialog',d=>d.accept());await p.locator('[data-list-delete=n1]').click();await p.waitForFunction(()=>state.records[0].body.deleted);assert.equal(await p.locator('[data-record]').count(),0);await p.close();});
test('neuro summary print omits normal findings without miscounting untested fields',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LF"]').selectOption('normal');await p.locator('[data-finding="position.RF"]').selectOption('delayed');await save(p);await p.locator('[data-detail=print-options] summary').click();await p.locator('[data-print-mode]').selectOption('summary');const wait=p.waitForEvent('popup');if(!await p.locator('[data-detail=print-options]').getAttribute('open').then(v=>v!==null))await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-nr=print]').click();const out=await wait;await out.waitForLoadState();const text=await out.locator('body').innerText();assert.match(text,/기록 2항목/);assert.match(text,/발 위치반응/);assert.match(text,/우전/);assert.match(text,/지연/);assert.doesNotMatch(await out.locator('tbody').innerText(),/정상/);await out.close();await p.close();});
