test('neuro registered comparison loads time before selection with bounded requests',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const r=state.records[0];r.patient_id='p1';r.body.neuroChart.time='08:30';for(let i=2;i<=9;i++){const x=structuredClone(r);x.id='n'+i;x.body.neuroChart.time='09:'+String(i).padStart(2,'0');state.records.push(x);}sessionStorage.setItem('mock-records',JSON.stringify(state.records));});await p.reload();await p.locator('[data-nr=history]').click();await p.locator('[data-prior-choice]').waitFor();assert.equal(await p.locator('[data-prior-choice] option').count(),7);assert.match(await p.locator('[data-prior-choice]').innerText(),/09:02/);assert.ok(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('?view=neuro')).length)<=7);await p.locator('[data-prior-more]').click();await p.waitForFunction(()=>document.querySelectorAll('[data-prior-choice] option').length===9);await p.close();});
test('neuro clinical aid is local and never replaces clinician assessment',async()=>{const p=await page();await begin(p);await p.locator('[data-detail=clinical-aid]>summary').click();await p.locator('[data-aid-context]').click();await p.locator('[data-field=context]').selectOption('awake');await p.locator('[data-finding=headTilt]').selectOption('left');await p.locator('[data-finding=nystagmus]').selectOption('vertical');await p.locator('[data-field=assessment]').fill('수의사 판단 유지');await save(p);assert.match(await p.locator('[data-clinical-aid]').innerText(),/중추 전정계/);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.assessment),'수의사 판단 유지');assert.deepEqual(await p.evaluate(()=>state.records[0].body.neuroChart.localization),[]);assert.ok(!await p.evaluate(()=>state.requests.some(r=>/openai|generate|ai\//.test(r.p))));await p.close();});
test('neuro existing record staff list refreshes and failed staff read can retry',async()=>{const p=await page();await begin(p);await p.reload();await p.locator('[data-finding="position.LF"]').waitFor();await p.waitForFunction(()=>document.querySelectorAll('#nr-members option').length===1);await p.evaluate(async()=>{view.dispose();const orig=api;window.staffFail=true;api=async(p,o)=>{if(p.endsWith('/members')&&staffFail)throw Error('직원 조회 실패');return orig(p,o);};view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.locator('#nr-basic > summary').click();await p.locator('[data-staff-retry]').waitFor();await p.evaluate(()=>staffFail=false);await p.locator('[data-staff-retry]').click();await p.waitForFunction(()=>document.querySelectorAll('#nr-members option').length===1);assert.equal(await p.locator('[data-staff-retry]').count(),0);await p.close();});
