test('neuro prior details are reused until explicit refresh',async()=>{const p=await page();await begin(p);await p.locator('[data-nr=recheck]').click();await p.locator('[data-nr=save]').click();await p.locator('[data-nr=history]').click();await p.locator('[data-prior-choice]').waitFor();const before=await p.evaluate(()=>state.requests.filter(r=>r.p.endsWith('/cases/n1?view=neuro')).length);await p.locator('[data-prior-choice]').selectOption('n1');await p.locator('[data-prior-choice]').selectOption('');await p.locator('[data-prior-choice]').selectOption('n1');assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.endsWith('/cases/n1?view=neuro')).length),before);await p.locator('[data-compare-refresh]').click();await p.waitForFunction(n=>state.requests.filter(r=>r.p.endsWith('/cases/n1?view=neuro')).length>n,before);await p.close();});
test('neuro prior auto comparison selects only an earlier same-patient exam',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const r=state.records[0];r.patient_id='p1';r.body.neuroChart.time='12:00';for(const [id,time] of [['prior','11:00'],['future','13:00']]){const x=structuredClone(r);x.id=id;x.body.neuroChart.time=time;state.records.push(x);}sessionStorage.setItem('mock-records',JSON.stringify(state.records));});await p.reload();await p.locator('[data-nr=history]').click();await p.waitForFunction(()=>document.querySelector('[data-prior-choice]')?.value==='prior');assert.match(await p.locator('[data-comparison-results]').innerText(),/11:00/);await p.close();});
for(const width of [360,820,1440])test('neuro compact workflow stays readable at '+width,async()=>{const p=await page(width),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.locator('[data-nr=new]').click();await p.locator('[data-patient-search]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick]').click();await p.locator('[data-nr=save]').click();await p.locator('[data-field=context]').waitFor();assert.match(await p.locator('[data-patient-brief]').innerText(),/중성화 수컷/);assert.match(await p.locator('[data-patient-brief]').innerText(),/세/);assert.ok(await p.locator('[data-field=context]').isVisible());assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.locator('[data-quick="position.LF"]').scrollIntoViewIfNeeded();assert.ok((await p.locator('[data-quick="position.LF"]').boundingBox()).width>=40);if(process.env.NEURO_SCREENSHOT_DIR){await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-'+width+'.png'),fullPage:true});}assert.deepEqual(errors,[]);await p.close();});

test('neuro full print matrix preserves every recorded field and emits a compact PDF',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const chart=state.records[0].body.neuroChart;for(const f of NeuroRecord.allFields)chart.findings[f.id]=f.normal||NeuroRecord.schema.options[f.type]?.[0]?.[0]||'unable';chart.context='awake';sessionStorage.setItem('mock-records',JSON.stringify(state.records));});await p.reload();await p.locator('[data-detail=print-options]').waitFor();const wait=p.waitForEvent('popup');if(!await p.locator('[data-detail=print-options]').getAttribute('open').then(v=>v!==null))await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-nr=print]').click();const out=await wait;await out.waitForLoadState();const rows=await p.evaluate(()=>NeuroRecord.schema.rows.map(r=>r.label.replace(/ \(Hopping\)/,'')));for(const label of rows)assert.ok((await out.locator('body').innerText()).includes(label),label);assert.equal(await out.locator('.nr-print-matrices section').count(),5);assert.equal(await out.locator('[data-print-finding]').count(),71);for(const id of await p.evaluate(()=>NeuroRecord.allFields.map(f=>f.id))){assert.notEqual(await out.locator('[data-print-finding="'+id+'"]').innerText(),'—',id);}if(process.env.NEURO_SCREENSHOT_DIR){await out.pdf({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-full.pdf'),preferCSSPageSize:true,printBackground:true});await out.screenshot({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-print.png'),fullPage:true});}await out.close();await p.close();});

test('neuro bilingual names cover every exam and print, without changing field identifiers',async()=>{const p=await page();await begin(p);const rows=await p.evaluate(()=>NeuroRecord.schema.rows.map(r=>({key:r.key,en:NeuroRecord.englishNames[r.key]})));assert.equal(rows.length,36);for(const r of rows){assert.ok(r.en);assert.equal(await p.locator('[data-exam-row="'+r.key+'"] .nr-exam-en').textContent(),r.en);}await p.locator('[data-finding="position.LF"]').selectOption('delayed');await save(p);const wait=p.waitForEvent('popup');if(!await p.locator('[data-detail=print-options]').getAttribute('open').then(v=>v!==null))await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-nr=print]').click();const out=await wait;await out.waitForLoadState();assert.match(await out.locator('body').innerText(),/Proprioceptive positioning/);await out.close();await p.close();});
