test('neuro review keeps all four side coordinates fixed',async()=>{const p=await page(1440);await begin(p);await p.locator('[data-finding="position.RF"]').selectOption('delayed');const boxes=await p.locator('[data-exam-row=position] [data-cell]').evaluateAll(es=>es.map(e=>({x:e.getBoundingClientRect().x,w:e.getBoundingClientRect().width})));await p.locator('[data-review-mode]').selectOption('abnormal');const after=await p.locator('[data-exam-row=position] [data-cell]').evaluateAll(es=>es.map(e=>({x:e.getBoundingClientRect().x,w:e.getBoundingClientRect().width})));assert.deepEqual(after,boxes);assert.equal(await p.locator('[data-exam-row=position] .nr-filtered-out').count(),3);await p.close();});
test('neuro recheck imports selected history and plan without exam or context reuse',async()=>{const p=await page();await begin(p);await p.locator('[data-field=history]').fill('이전 경과');await p.locator('[data-field=plan]').fill('재검 계획');await p.locator('[data-field=context]').selectOption('sedated');await p.locator('[data-finding="position.LF"]').selectOption('absent');await save(p);await p.locator('[data-nr=recheck]').click();await p.locator('.nr-recheck summary').click();await p.locator('[data-import=history]').click();await p.locator('[data-nr=save]').click();assert.equal(await p.locator('[data-field=history]').inputValue(),'이전 경과');assert.equal(await p.locator('[data-field=plan]').inputValue(),'');assert.equal(await p.locator('[data-field=context]').inputValue(),'');assert.equal(await p.locator('[data-finding="position.LF"]').inputValue(),'');await p.locator('.nr-recheck summary').click();await p.locator('[data-field=plan]').fill('새 계획');await p.locator('[data-import=plan]').click();assert.equal(await p.locator('[data-field=plan]').inputValue(),'새 계획\n재검 계획');assert.ok(await p.locator('[data-import=plan]').isDisabled());await save(p);assert.deepEqual(await p.evaluate(()=>state.records[1].body.neuroChart.findings),{});await p.close();});
test('neuro summary clipboard and fallback include manual findings but exclude generated aid',async()=>{const p=await page();await begin(p);await p.locator('[data-field=assessment]').fill('의료진 판단');await p.locator('[data-finding="position.LF"]').selectOption('delayed');await p.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async t=>{window.copied=t;}}}));await p.locator('[data-nr=copy-summary]').click();await p.waitForFunction(()=>window.copied);const copied=await p.evaluate(()=>copied);assert.match(copied,/Proprioceptive positioning/);assert.match(copied,/의료진 판단/);assert.doesNotMatch(copied,/입력 소견 기반 참고|검토 부위/);await p.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async()=>{throw Error('denied');}}}));await p.locator('[data-nr=copy-summary]').click();assert.equal(await p.locator('[data-copy-fallback] textarea').inputValue(),copied);await p.close();});
test('neuro clinical status is explicit and a failed completion is not labelled saved complete',async()=>{const p=await page();await begin(p);assert.equal(await p.locator('[data-clinical-status]').innerText(),'작성 중');await p.evaluate(()=>state.fail=true);await p.locator('[data-nr=complete]').click();await p.locator('[data-clinical-status]').filter({hasText:'저장 대기'}).waitFor();assert.match(await p.locator('[data-clinical-status]').innerText(),/^작성 중/);await p.evaluate(()=>state.fail=false);await save(p);assert.equal(await p.locator('[data-clinical-status]').innerText(),'작성 완료');await p.locator('[data-field=assessment]').fill('정정');await save(p);assert.equal(await p.locator('[data-clinical-status]').innerText(),'완료 후 수정');await p.close();});
test('neuro typing does not rebuild findings or clinical aid while changed findings update immediately',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{window.renders=0;window.mo=new MutationObserver(()=>renders++);mo.observe(document.querySelector('[data-clinical-aid]'),{childList:true});});await p.locator('[data-field=assessment]').pressSequentially('진료 중 문장 입력');await p.waitForTimeout(400);assert.equal(await p.evaluate(()=>renders),0);await p.locator('[data-finding="position.LF"]').selectOption('delayed');assert.ok(await p.evaluate(()=>renders)>0);assert.match(await p.locator('[data-summary]').innerText(),/지연/);await p.close();});
for(const width of [360,820,1440])test('neuro section navigation and bilingual layout '+width,async()=>{const p=await page(width);const errors=[];p.on('pageerror',e=>errors.push(e.message));await begin(p);assert.equal(await p.locator('[data-jump]').count(),7);await p.locator('[data-jump=nr-cranial]').click();await p.waitForTimeout(500);assert.ok(await p.locator('#nr-cranial').isVisible());assert.equal(await p.locator('[data-jump=nr-cranial]').getAttribute('aria-current'),'true');assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2));if(process.env.NEURO_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-flow-'+width+'.png')});assert.deepEqual(errors,[]);await p.close();});

test('neuro pain review displays explicit values and empty review explains absence',async()=>{const p=await page();await begin(p);await p.locator('[data-review-mode]').selectOption('abnormal');assert.match(await p.locator('[data-review-count]').innerText(),/기록된 이상 소견·평가 제한이 없습니다/);await p.locator('[data-review-mode]').selectOption('all');await p.locator('[data-quick=cervicalPain][data-value=present]').click();await p.locator('[data-quick=thoracicPain][data-value=unable]').click();await p.locator('[data-review-mode]').selectOption('abnormal');assert.equal(await p.locator('[data-read-result=cervicalPain]').innerText(),'통증 있음');assert.equal(await p.locator('[data-read-result=thoracicPain]').innerText(),'평가 불가');assert.ok(!await p.locator('[data-quick=cervicalPain][data-value=present]').isVisible());await p.locator('[data-edit-finding=cervicalPain]').click();await p.locator('[data-quick=cervicalPain][data-value=absent]').click();await p.locator('[data-return-review]').click();assert.ok(!await p.locator('[data-exam-row=cervicalPain]').isVisible());await p.close();});
test('neuro invalid nested input expands all ancestors and clears field error on correction',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const e=document.querySelector('[data-field="patient.birthDate"]');e.value='2099-01-01';e.dispatchEvent(new Event('input'));document.querySelectorAll('#nr-basic,.nr-patient').forEach(x=>x.open=false);});await p.locator('[data-nr=save]').click();const field=p.locator('[data-field="patient.birthDate"]');assert.ok(await field.isVisible());assert.equal(await field.getAttribute('aria-invalid'),'true');assert.equal(await p.evaluate(()=>document.activeElement.dataset.field),'patient.birthDate');assert.match(await p.locator('[data-input-error]').innerText(),/생년월일/);await field.fill('2020-01-01');assert.equal(await field.getAttribute('aria-invalid'),null);await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.patient.birthDate),'2020-01-01');await p.close();});
test('neuro undo stays in sticky header at lower exam and names the affected exam',async()=>{const p=await page(390);await begin(p);await p.locator('[data-jump=nr-pain]').click();await p.locator('[data-quick=cervicalPain][data-value=present]').click();const undo=p.locator('[data-nr=undo-findings]');assert.match(await undo.innerText(),/경부 촉진/);assert.ok(await undo.evaluate(e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight;}));await undo.click();await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.findings.cervicalPain),undefined);await p.close();});
test('neuro copied chart summary includes recorded patient identifiers and demographics',async()=>{const p=await page();await p.locator('[data-nr=new]').click();await p.locator('[data-patient-search]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick]').click();await p.locator('[data-nr=save]').click();await p.locator('[data-nr=copy-summary]').waitFor();await p.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async t=>window.summaryText=t}}));await p.locator('[data-nr=copy-summary]').click();await p.waitForFunction(()=>window.summaryText);const line=await p.evaluate(()=>summaryText.split('\n')[0]);for(const text of ['합성 환자','TEST-101','합성 품종','중성화 수컷','5 kg'])assert.ok(line.includes(text),text);assert.match(line,/세/);await p.close();});
test('neuro mobile menu arrows and current section remain discoverable without horizontal page shift',async()=>{const p=await page(360);await begin(p);await p.locator('[data-nav-shift="1"]').click();assert.ok(await p.locator('.nr-jumps').evaluate(e=>e.scrollLeft>0));await p.locator('[data-jump=nr-assessment]').click();assert.ok(await p.locator('[data-jump=nr-assessment]').evaluate(e=>{const r=e.getBoundingClientRect(),n=e.parentElement.getBoundingClientRect();return r.left>=n.left-1&&r.right<=n.right+1;}));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2));await p.locator('[data-nav-shift="-1"]').click();await p.locator('[data-jump=nr-observation]').click();assert.equal(await p.locator('[data-jump=nr-observation]').getAttribute('aria-current'),'true');if(process.env.NEURO_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-polish-mobile.png')});await p.close();});
test('neuro list times load only visible records with bounded concurrency and reuse cache',async()=>{const p=await page(390);await begin(p);await p.evaluate(async()=>{const original=structuredClone(state.records[0]);state.records=[];for(let i=1;i<=20;i++){const r=structuredClone(original);r.id='n'+i;r.patient.name='합성 '+i;r.body.neuroChart.time='09:'+String(i).padStart(2,'0');state.records.push(r);}window.detailActive=0;window.detailPeak=0;window.detailReads=[];const prior=api;api=async(path,o)=>{if(path.includes('?view=neuro')){detailReads.push(path);detailPeak=Math.max(detailPeak,++detailActive);await new Promise(r=>setTimeout(r,50));try{return await prior(path,o);}finally{detailActive--;}}return prior(path,o);};view.dispose();sessionStorage.clear();view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.locator('[data-list-time=n1]').filter({hasText:'09:01'}).waitFor();await p.waitForTimeout(200);assert.ok(await p.evaluate(()=>detailPeak<=2));const count=await p.evaluate(()=>detailReads.length);assert.ok(count>0&&count<20,count);await p.locator('[data-nr=refresh]').click();await p.waitForTimeout(200);assert.equal(await p.evaluate(()=>detailReads.length),count);await p.locator('[data-record=n20]').scrollIntoViewIfNeeded();await p.locator('[data-list-time=n20]').filter({hasText:'09:20'}).waitFor();assert.ok(await p.evaluate(()=>detailReads.length<20));await p.close();});
test('neuro supplied list times avoid detail reads and missing time is explicit',async()=>{const p=await page();await begin(p);await p.evaluate(async()=>{const r=state.records[0];state.pages={first:{items:[{id:r.id,patient:r.patient,date:r.body.neuroChart.date,time:'13:42',clinicalStatus:'inProgress'}],next:null}};view.dispose();sessionStorage.clear();view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});assert.match(await p.locator('[data-list-time=n1]').innerText(),/13:42/);assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('?view=neuro')).length),0);await p.evaluate(()=>state.pages.first.items[0].time='');await p.locator('[data-nr=refresh]').click();await p.locator('[data-list-time=n1]').filter({hasText:'시각 미기록'}).waitFor();await p.close();});
test('neuro pending list-time response cannot leak across account scope',async()=>{const p=await page();await begin(p);await p.evaluate(async()=>{const orig=api;window.pendingTime=null;api=async(path,o)=>{if(path.includes('?view=neuro')){const data=await orig(path,o);return new Promise(resolve=>window.pendingTime=()=>resolve(data));}return orig(path,o);};view.dispose();sessionStorage.clear();view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.waitForFunction(()=>window.pendingTime);await p.evaluate(()=>{state.scope='other:staff';view.sync();pendingTime();});await p.waitForTimeout(100);assert.ok(!(await p.locator('#root').innerText()).includes('합성 신경환자'));await p.close();});

test('neuro list-time failure stays bounded and explicit refresh retries',async()=>{const p=await page();await begin(p);await p.evaluate(async()=>{window.timeFail=true;window.timeAttempts=0;const orig=api;api=async(path,o)=>{if(path.includes('?view=neuro')){timeAttempts++;if(timeFail)throw Error('합성 시각 조회 실패');}return orig(path,o);};view.dispose();sessionStorage.clear();view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.locator('[data-list-time=n1]').filter({hasText:'시각 조회 실패'}).waitFor();await p.waitForTimeout(150);assert.equal(await p.evaluate(()=>timeAttempts),1);await p.evaluate(()=>timeFail=false);await p.locator('[data-nr=refresh]').click();await p.waitForFunction(()=>!document.querySelector('[data-list-time=n1]').textContent.includes('시각'));assert.equal(await p.evaluate(()=>timeAttempts),2);await p.close();});
test('neuro streamline navigation preserves review filters and empty sections offer explicit input',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LF"]').selectOption('delayed');await save(p);const before=await p.evaluate(()=>JSON.stringify(state.records[0].body.neuroChart.findings));await p.locator('[data-review-mode]').selectOption('abnormal');await p.locator('[data-jump=nr-postural]').click();assert.equal(await p.locator('[data-review-mode]').inputValue(),'abnormal');assert.ok(await p.locator('[data-read-result="position.LF"]').isVisible());await p.locator('[data-jump=nr-cranial]').click();assert.equal(await p.locator('[data-review-mode]').inputValue(),'abnormal');assert.match(await p.locator('#nr-cranial [data-review-empty]').innerText(),/해당하는.*결과가 없습니다/);assert.equal(await p.locator('[data-jump=nr-cranial]').getAttribute('aria-current'),'true');await p.locator('#nr-cranial [data-show-input]').click();assert.equal(await p.locator('[data-review-mode]').inputValue(),'all');assert.equal(await p.locator('[data-review-empty]').count(),0);assert.ok(await p.locator('[data-finding="menace.L"]').isVisible());assert.equal(await p.evaluate(()=>JSON.stringify(state.records[0].body.neuroChart.findings)),before);await p.close();});
test('neuro streamline manual assessment precedes collapsed aid while alerts stay visible',async()=>{const p=await page();await begin(p);assert.equal(await p.locator('[data-detail=clinical-aid]').getAttribute('open'),null);assert.ok(await p.locator('[data-field=plan]').evaluate(e=>!!(e.compareDocumentPosition(document.querySelector('[data-detail=clinical-aid]'))&Node.DOCUMENT_POSITION_FOLLOWING)));await p.locator('[data-finding=mentation]').selectOption('coma');assert.ok(await p.locator('[data-aid-alerts] .nr-aid-alert').count()>0);assert.ok(await p.locator('[data-aid-alerts] .nr-aid-alert').first().isVisible());assert.equal(await p.locator('[data-detail=clinical-aid]').getAttribute('open'),null);await p.locator('[data-detail=clinical-aid]>summary').click();await p.locator('[data-field=assessment]').fill('검사자 판단');await save(p);assert.equal(await p.locator('[data-field=assessment]').inputValue(),'검사자 판단');await p.close();});
test('neuro streamline summary distinguishes explicit normal sides from untested and limited',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LF"]').selectOption('normal');await p.locator('[data-finding="position.RF"]').selectOption('normal');await p.locator('[data-finding="position.LH"]').selectOption('unable');await p.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async t=>window.copied=t}}));await p.locator('[data-nr=copy-summary]').click();await p.waitForFunction(()=>window.copied);const text=await p.evaluate(()=>copied),normal=text.split('\n').find(x=>x.startsWith('정상으로 기록한 검사:'));assert.match(normal,/좌전·우전/);assert.doesNotMatch(normal,/좌후|우후/);assert.match(text,/미검사: 68항목/);assert.match(text,/평가 제한: .*좌후.*평가 불가/);assert.doesNotMatch(text,/자동 진단|감별 참고문헌/);await p.close();});
test('neuro streamline search reset clears applied conditions and pagination',async()=>{const p=await page();await begin(p);await p.locator('[data-nr=back]').click();await p.locator('[data-list-search] [name=q]').fill('없는검색');await p.locator('[data-list-search] [name=status]').selectOption('complete');await p.locator('.nr-filter>summary').click();await p.locator('[name=from]').fill('2026-01-01');await p.locator('[name=to]').fill('2026-12-31');await p.locator('[name=vet]').fill('시험자');await p.locator('[data-list-search]>button').click();await p.locator('[data-search-reset]').waitFor();assert.match(await p.locator('.nr-search-applied').innerText(),/없는검색.*완료.*2026-01-01.*시험자/s);await p.locator('[data-search-reset]').click();await p.locator('[data-record=n1]').waitFor();assert.equal(await p.locator('[data-search-reset]').count(),0);const query=await p.evaluate(()=>state.requests.filter(x=>x.p.includes('/neuro?')).at(-1).p);for(const field of ['q','status','from','to','vet','cursor'])assert.ok(!new URL('https://test'+query).searchParams.get(field),field);await p.close();});
test('neuro streamline comparison keeps actual changes open and other groups collapsed',async()=>{const p=await page();await begin(p);await p.locator('[data-finding="position.LF"]').selectOption('absent');await p.locator('[data-finding="position.LH"]').selectOption('normal');await save(p);await p.locator('[data-nr=recheck]').click();await p.locator('[data-nr=save]').click();await p.locator('[data-finding="position.LF"]').selectOption('delayed');await p.locator('[data-finding="position.RF"]').selectOption('normal');await p.locator('[data-field=assessment]').fill('새 판단');await p.locator('[data-nr=history]').click();await p.locator('[data-prior-choice]').selectOption('n1');assert.match(await p.locator('.nr-comparison-counts').innerText(),/결과 변화 1 · 새로 평가 1 · 미검사·평가 제한 1/);assert.ok(await p.locator('[data-comparison-results]>h4').isVisible());for(const key of ['comparison-new','comparison-limited','comparison-clinical'])assert.equal(await p.locator('[data-detail='+key+']').getAttribute('open'),null);await p.locator('[data-detail=comparison-new]>summary').click();await p.locator('[data-field=assessment]').fill('새 판단 수정');await p.waitForTimeout(400);assert.notEqual(await p.locator('[data-detail=comparison-new]').getAttribute('open'),null);assert.equal(await p.locator('[data-detail=comparison-limited]').getAttribute('open'),null);await p.close();});
for(const width of [360,820,1440])test('neuro streamline compact header and print menu '+width,async()=>{const p=await page(width);await begin(p);assert.equal(await p.locator('[data-detail=print-options]>summary').innerText(),'인쇄·PDF');assert.ok(!await p.locator('[data-nr=print]').isVisible());assert.ok(await p.locator('[data-nr=save]').getAttribute('class').then(x=>x.includes('nr-save-status')));await p.locator('[data-detail=print-options]>summary').click();assert.ok(await p.locator('[data-nr=print]').isVisible());assert.ok(await p.locator('.nr-print-menu').evaluate(e=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1;}));await p.locator('[data-detail=print-options]>summary').click();await p.locator('[data-jump=nr-pain]').click();await p.locator('[data-quick=cervicalPain][data-value=present]').click();for(const selector of ['[data-nr=complete]','[data-nr=undo-findings]'])assert.ok(await p.locator(selector).evaluate(e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight;}));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2));if(process.env.NEURO_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.NEURO_SCREENSHOT_DIR,'neuro-streamline-'+width+'.png')});await p.close();});

test('reliability recheck retains last exam weight instead of directory weight and labels manual changes',async()=>{const p=await page();await p.locator('[data-nr=new]').click();await p.locator('[data-patient-search]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick]').click();await p.locator('[data-nr=save]').click();await p.locator('#nr-basic>summary').click();await p.locator('[data-field=weight]').fill('8');await save(p);await p.locator('[data-nr=recheck]').click();assert.equal(await p.locator('[data-field=weight]').inputValue(),'8');assert.match(await p.locator('[data-weight-origin]').innerText(),/직전 검사 체중/);await p.locator('[data-field=weight]').fill('8.2');assert.equal(await p.locator('[data-weight-origin]').innerText(),'직접 입력');await save(p);assert.equal(await p.evaluate(()=>state.records[1].body.neuroChart.weight),8.2);await p.locator('[data-nr=recheck]').click();await p.locator('[data-field=weight]').fill('');await save(p);await p.locator('[data-nr=recheck]').click();assert.equal(await p.locator('[data-field=weight]').inputValue(),'');await p.close();});
test('reliability completion failure retries same completion and reopening without reversing intent',async()=>{const p=await page();await begin(p);await p.evaluate(()=>state.fail=true);await p.locator('[data-nr=complete]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.locator('[data-nr=complete]').innerText(),'작성 완료 저장 재시도');assert.match(await p.locator('[data-clinical-status]').innerText(),/작성 중.*완료 저장 대기/);await p.evaluate(()=>state.fail=false);await p.locator('[data-nr=complete]').click();await p.waitForFunction(()=>document.querySelector('[data-nr=complete]')?.textContent==='작성 재개');assert.equal(await p.evaluate(()=>state.records[0].body.neuroChart.clinicalStatus),'complete');await p.evaluate(()=>state.fail=true);await p.locator('[data-nr=complete]').click();await p.locator('[data-nr-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.locator('[data-nr=complete]').innerText(),'작성 재개 저장 재시도');await p.evaluate(()=>state.fail=false);await p.locator('[data-nr=complete]').click();await p.waitForFunction(()=>state.records[0].body.neuroChart.clinicalStatus==='inProgress');assert.equal(await p.locator('[data-nr=complete]').innerText(),'작성 완료');const requests=await p.evaluate(()=>state.requests.filter(r=>r.method==='POST'&&r.p.endsWith('/events')).map(r=>JSON.parse(r.body)));assert.equal(requests[0].requestKey,requests[1].requestKey);assert.equal(requests[2].requestKey,requests[3].requestKey);await p.close();});
test('reliability failed comparison clears old results and offers retry for selected exam',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const r=state.records[0];r.patient_id='p1';r.body.neuroChart.time='12:00';for(const [id,time] of [['prior','10:00'],['other','11:00']]){const c=structuredClone(r);c.id=id;c.body.neuroChart.time=time;state.records.push(c);}sessionStorage.setItem('mock-records',JSON.stringify(state.records));});await p.reload();await p.locator('[data-nr=history]').click();await p.waitForFunction(()=>document.querySelector('[data-prior-choice]')?.value==='other');await p.evaluate(()=>{window.savedAPI=api;api=async(path,o)=>{if(path.includes('/cases/prior?'))throw Error('합성 조회 실패');return savedAPI(path,o);};const now=Date.now;Date.now=()=>now()+61000;});await p.locator('[data-prior-choice]').selectOption('prior');await p.locator('[data-compare-retry]').waitFor();assert.equal(await p.locator('[data-comparison-results]').getAttribute('data-prior'),null);assert.match(await p.locator('[data-comparison-results]').innerText(),/비교 조회 실패/);assert.equal(await p.locator('.nr-comparison-counts').count(),0);await p.evaluate(()=>api=savedAPI);await p.locator('[data-compare-retry]').click();await p.waitForFunction(()=>document.querySelector('[data-comparison-results]')?.dataset.prior==='prior');await p.close();});
async function cachedList(p){await begin(p);await p.locator('[data-nr=back]').click();await p.evaluate(async()=>{view.dispose();view=NeuroRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.waitForFunction(()=>!document.querySelector('[data-list-time]')?.textContent.includes('확인 중')&&state.requests.some(r=>r.p.includes('/cases/n1?')));await p.evaluate(()=>state.requests=[]);}
test('reliability list detail is reused after revision confirmation',async()=>{const p=await page();await cachedList(p);await p.locator('[data-record=n1]').click();await p.locator('[data-finding]').first().waitFor();const reads=await p.evaluate(()=>state.requests.map(r=>r.p));assert.equal(reads.filter(x=>x.includes('/cases/n1?')).length,0);assert.equal(reads.filter(x=>x.endsWith('/cases/n1/sync')).length,1);await p.close();});
test('reliability newer revision bypasses cached detail',async()=>{const p=await page();await cachedList(p);await p.evaluate(()=>{state.records[0].revision++;state.records[0].body.neuroChart.assessment='새로운 검사 판단';});await p.locator('[data-record=n1]').click();await p.locator('[data-finding]').first().waitFor();assert.equal(await p.locator('[data-field=assessment]').inputValue(),'새로운 검사 판단');assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('/cases/n1?')).length),1);await p.close();});
test('reliability expired detail and failed revision checks never show stale record',async()=>{const p=await page();await cachedList(p);await p.evaluate(()=>state.fail=true);await p.locator('[data-record=n1]').click();await p.locator('[data-nr=new]').waitFor();assert.equal(await p.locator('[data-finding]').count(),0);await p.evaluate(()=>{state.fail=false;const now=Date.now;Date.now=()=>now()+61000;state.requests=[];});await p.locator('[data-record=n1]').click();await p.locator('[data-finding]').first().waitFor();assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('/cases/n1?')).length),1);await p.close();});
test('reliability invalid search dates preserve previously applied filters',async()=>{const p=await page();await p.locator('[name=q]').fill('기존 검색');await p.locator('[data-list-search] button').click();await p.locator('.nr-search-applied').waitFor();await p.locator('[name=q]').fill('잘못된 새 검색');await p.locator('[name=status]').selectOption('complete');await p.locator('.nr-filter>summary').click();await p.locator('[name=from]').fill('2026-11-02');await p.locator('[name=to]').fill('2026-11-01');const before=await p.evaluate(()=>state.requests.length);await p.locator('[data-list-search] button').click();assert.equal(await p.locator('[name=to]').getAttribute('aria-invalid'),'true');assert.equal(await p.evaluate(()=>state.requests.length),before);await p.locator('[data-nr=refresh]').click();await p.waitForFunction(()=>document.querySelector('[name=q]')?.value==='기존 검색');assert.equal(await p.locator('[name=status]').inputValue(),'');assert.equal(await p.locator('[name=from]').inputValue(),'');assert.match(await p.locator('.nr-search-applied').innerText(),/기존 검색/);await p.close();});
test('reliability printing waits for bundled Korean font and retains readable fallback on failure',async()=>{for(const fail of [false,true]){const p=await page();await begin(p);await p.evaluate(()=>{const base=document.createElement('base');base.href=location.origin+'/print/';document.head.append(base);const open=window.open;window.open=(...args)=>{const w=open(...args),write=w.document.write.bind(w.document);w.document.write=(...html)=>{write(...html);w.print=()=>{w.document.documentElement.dataset.printed=w.document.fonts.status;w.document.documentElement.dataset.fontLoaded=String([...w.document.fonts].some(f=>f.family==='Pretendard'&&f.status==='loaded'));};};return w;};});await p.context().route('**/print/pretendard-variable-1.3.9.woff2',async route=>{await new Promise(r=>setTimeout(r,400));if(fail)await route.abort();else await route.fulfill({contentType:'font/woff2',body:fs.readFileSync(path.join(root,'pretendard-variable-1.3.9.woff2'))});});await p.locator('[data-detail=print-options]>summary').click();const waiting=p.waitForEvent('popup');await p.locator('[data-nr=print]').click();const out=await waiting;await out.waitForFunction(()=>document.documentElement.dataset.printed);assert.equal(await out.evaluate(()=>document.documentElement.dataset.printed),'loaded');if(!fail)assert.equal(await out.evaluate(()=>document.documentElement.dataset.fontLoaded),'true');else assert.match(await p.locator('[data-nr-status]').innerText(),/기본 글꼴/);await out.close();await p.close();}});

test('shared confirmation protects and deletes the exact neuro record',async()=>{const p=await page();await begin(p);await p.addScriptTag({url:url+'/clinic-dialog.js'});await p.addStyleTag({url:url+'/clinic-calm.css'});await p.locator('[data-nr=delete]').click();await p.locator('.cs-action-dialog').waitFor();assert.match(await p.locator('.cs-action-context').innerText(),/합성/);await p.locator('[data-dialog-cancel]').click();assert.equal(await p.evaluate(()=>!!state.records[0].body.deleted),false);await p.locator('[data-nr=delete]').click();await p.locator('[data-dialog-confirm]').click();await p.waitForFunction(()=>state.records[0].body.deleted===true);assert.equal(await p.locator('.cs-action-dialog').count(),0);await p.close();});

for(const width of [390,1440])test('entry choices neuro history saves structured onset and legacy memo '+width,async()=>{const p=await page(width);await p.addInitScript({path:path.join(root,'record-input-choices.js')});await p.addScriptTag({url:url+'/record-input-choices.js'});await p.addStyleTag({url:url+'/record-input-choices.css'});await begin(p);const h=p.locator('[data-record-structured=history]');await h.locator('[data-ric-index="0"]').selectOption('1–3일 전');await h.locator('[data-ric-index="1"]').selectOption('갑작스러운 시작');await h.locator('[data-ric-index="2"]').selectOption('반복·간헐적');await h.locator('textarea').fill('합성 기존 메모');await save(p);assert.match(await p.evaluate(()=>state.records[0].body.neuroChart.history),/증상 시작: 1–3일 전.*발병 양상: 갑작스러운 시작.*합성 기존 메모/s);await p.reload();await h.waitFor();assert.equal(await h.locator('[data-ric-index="0"]').inputValue(),'1–3일 전');assert.equal(await h.locator('textarea').inputValue(),'합성 기존 메모');assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.close();});
